function loadPage(storage) {
  const listeners = {};
  const cartCount = { textContent: "0" };
  const context = {
    localStorage: {
      getItem: (key) => storage.get(key) ?? null,
      setItem: (key, value) => storage.set(key, String(value)),
    },
    window: { addEventListener: (name, callback) => { listeners[name] = callback; } },
    document: { getElementById: (id) => id === "cartCount" ? cartCount : null },
    JSON,
    String,
  };
  vm.runInNewContext(inlineScript, context, { filename: "index.html#inline-script" });
  listeners.load();
  return { context, cartCount };
}

function loadCartFromStorage() {
  const savedCart = localStorage.getItem("quickCartItems");
  if (savedCart) {
    cartItems = JSON.parse(savedCart);
    cartCount = cartItems.reduce((total, item) => total + item.quantity, 0);
  }
}

function addToCart(productName, price) {
  const existingItem = cartItems.find((item) => item.name === productName);
  if (existingItem) existingItem.quantity += 1;
  else cartItems.push({ name: productName, price, quantity: 1 });
  cartCount += 1;
  saveCartToStorage();
  updateCartDisplay();
}

